@Component
public class ResilientKafkaConsumer {

    @KafkaListener(topics = "orders-topic", groupId = "order-processor-group")
    public void listen(ConsumerRecord<String, Order> record, Acknowledgment acknowledgment) {
        try {
            processOrder(record.value());
            acknowledgment.acknowledge();
        } catch (DataAccessException ex) {
            // Transient database failure: throw to trigger retry interceptor or backoff
            throw new TransientProcessingException("Database offline", ex);
        } catch (IllegalArgumentException ex) {
            // Poison pill: Log and route directly to DLT or let DLT recoverer catch max failures
            throw new NonTransientProcessingException("Malformed payload", ex);
        }
    }

    private void processOrder(Order order) {
        if (order.getAmount() == null) {
            throw new IllegalArgumentException("Order amount cannot be null");
        }
    }
}
